    finally:
        EVENTS.remove(ws)


@sock.route("/ws/events")
def ws_events(ws):
    EVENTS.add(ws, "events")
    # Gửi snapshot ngay khi kết nối
    try:
        EVENTS.push("events", {"type": "status", "status": status_dict()})
        EVENTS.push("events", {"type": "botsnapshot", "bots": sorted(running_bots())})
        while True:
            if ws.receive() is None:
                break
    except Exception:
        pass
    finally:
        EVENTS.remove(ws)


# ============================================================
