charArray MapItemSavedData::getUpdatePacket(shared_ptr<ItemInstance> itemInstance, Level *level, shared_ptr<Player> player)
{
	AUTO_VAR(it, carriedByPlayers.find(player));
	if (it == carriedByPlayers.end() ) return charArray();

