   private MapColor(int i, int j) {
      if (i >= 0 && i <= 63) {
         this.id = i;
         this.col = j;
         MATERIAL_COLORS[i] = this;
      } else {
         throw new IndexOutOfBoundsException("Map colour ID must be between 0 and 63 (inclusive)");
      }
   }

   public int calculateRGBColor(MapColor.Brightness mapcolor_brightness) {
      if (this == NONE) {
         return 0;
      } else {
         int i = mapcolor_brightness.modifier;
         int j = (this.col >> 16 & 255) * i / 255;
         int k = (this.col >> 8 & 255) * i / 255;
         int l = (this.col & 255) * i / 255;
         return -16777216 | l << 16 | k << 8 | j;
      }
   }

   public static MapColor byId(int i) {
      Preconditions.checkPositionIndex(i, MATERIAL_COLORS.length, "material id");
      return byIdUnsafe(i);
   }

   private static MapColor byIdUnsafe(int i) {
      MapColor mapcolor = MATERIAL_COLORS[i];
      return mapcolor != null ? mapcolor : NONE;
   }

   public static int getColorFromPackedId(int i) {
      int j = i & 255;
      return byIdUnsafe(j >> 2).calculateRGBColor(MapColor.Brightness.byIdUnsafe(j & 3));
   }

   public byte getPackedId(MapColor.Brightness mapcolor_brightness) {
      return (byte)(this.id << 2 | mapcolor_brightness.id & 3);
   }

   public static enum Brightness {
      LOW(0, 180),
      NORMAL(1, 220),
      HIGH(2, 255),
      LOWEST(3, 135);

      private static final MapColor.Brightness[] VALUES = new MapColor.Brightness[]{LOW, NORMAL, HIGH, LOWEST};
      public final int id;
      public final int modifier;

      private Brightness(int i, int j) {
         this.id = i;
         this.modifier = j;
      }

      public static MapColor.Brightness byId(int i) {
         Preconditions.checkPositionIndex(i, VALUES.length, "brightness id");
         return byIdUnsafe(i);
      }

      static MapColor.Brightness byIdUnsafe(int i) {
         return VALUES[i];
      }
   }
}

