   const filled = filledPixelCount(map.buffer);
   const cols = packet.columns || 0;

   if (packet.columns > 0) {
     console.log(`[!][${now()}] map packet id=${mapId} patch=${cols}x${packet.rows}@(${packet.x},${packet.y}) data=${packet.data.length}B filled=${filled}/16384`);
   }
   if (changed) {
     saveDump(mapId, map);
   }
 }

